import { Component } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { Observable } from 'rxjs';
import { Job } from 'src/app/landing/models/job';
import { CompanyService } from 'src/app/service/company/company.service';
import { JobService } from 'src/app/service/job/job.service';
import { JobseekerService } from 'src/app/service/jobseeker/jobseeker.service';

@Component({
  selector: 'app-view-job',
  templateUrl: './view-job.component.html',
  styleUrls: ['./view-job.component.css']
})
export class ViewJobComponent {

constructor(private jobService : JobService, private route : ActivatedRoute,
    private companyService: CompanyService,
    private jobSeekerService: JobseekerService,
    private router: Router
){}




job! : Job;
jobSkills : any[] = [];

getJobByJobId(id : number){
  this.jobService.getJobById(id).subscribe({
    next : (result) => {
  this.job = result;
  this.jobSkills = this.job.skills;
    },
    error : (err) =>{
    console.log(err);

    }
  });
}


 allJobs: Job[] = [];

  isLoggedIn = false;
  initials = '';
  profileRoute = '/';



  ngOnInit(): void {

    this.isLoggedIn = !!localStorage.getItem('token');

    if (this.isLoggedIn) {

      const role = localStorage.getItem('role');
      const id = Number(localStorage.getItem('id'));

      if (role === 'COMPANY') {

        this.profileRoute = '/company/dashboard';

        this.companyService.getCompanyById(id).subscribe({
          next: (company: any) => {
            if (company?.companyName) {
              this.initials = company.companyName
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          },
          error: (err) => console.error(err)
        });

      } else {

        this.profileRoute = '/seeker/dashboard';

        this.jobSeekerService.getJobSeekerById(id).subscribe({
          next: (user: any) => {


            const name =
              user.userName ??
              `${user.firstName ?? ''} ${user.lastName ?? ''}`.trim();

            if (name) {
              this.initials = name
                .split(' ')
                .map((x: string) => x.charAt(0))
                .join('')
                .substring(0, 2)
                .toUpperCase();
            }
          },
          error: (err) => console.error(err)
        });
      }
    }

  const jobId = Number(this.route.snapshot.paramMap.get("id"));
  const jobSeekerId = Number(localStorage.getItem("id"));

  this.jobService.getSavedJobs(jobSeekerId).subscribe({
    next: (jobs: Job[]) => {
      this.isjobSaved = jobs.some(job => Number(job.jobId) === jobId);
    },
    error: (err) => console.error(err)
  });   


    this.getJobByJobId(jobId);
  }




  logout(): void {
    localStorage.clear();
    this.router.navigate(['/']);
  }

  goToProfile(): void {
    this.router.navigate([this.profileRoute]);
  };

isjobSaved= false;
  saveJobToProfile(){

    const jobId = Number(this.route.snapshot.paramMap.get("id"));
    const jobSeekerId = Number(localStorage.getItem("id"));





    this.jobService.saveJobToProfile(jobId, jobSeekerId).subscribe({
      next: (result) => {
        this.isjobSaved = true;
      },
      error: (err) => {
        console.log(err);
      }
    });

  }


}
<div class="page">
  <app-header variant="guest"></app-header>

  <div class="app-shell">
    <main class="main">

      <div class="breadcrumb"><a routerLink="/job/all-jobs">Jobs</a> / <span>{{ job?.jobTitle }}</span></div>
      <div class="card-row" style="grid-template-columns:2fr 1fr;align-items:start;">
        <div>
          <div style="display:flex;justify-content:space-between;align-items:flex-start;">
            <h1 style="font-size:26px;">{{job.jobTitle}} </h1><span class="chip chip-open">Open</span>
          </div>
          <p class="muted" style="margin-top:6px;">{{job.companyName}} · {{job.location}}, IN · {{job.postedDate |
            date}} </p>
          <div class="skill-tags" style="margin-top:16px;">
            <span *ngFor="let skill of jobSkills" class="skill-tag">{{skill}}</span>

          </div>
          <div class="card" style="margin-top:24px;">
            <p style="font-size:14px;color:var(--ink-soft);">{{job.description}}</p>
            <div class="card-row-3" style="margin-top:20px;">
              <div><span class="mono-label">Experience</span>
                <p style="margin-top:4px;font-weight:600;">{{job.experience}}</p>
              </div>
              <div><span class="mono-label">Salary</span>
                <p style="margin-top:4px;font-weight:600;">{{job.salary | currency}}</p>
              </div>
              <div><span class="mono-label">Apply by</span>
                <p style="margin-top:4px;font-weight:600;">{{job.endDate | date}}</p>
              </div>
            </div>
          </div>
        </div>
        <div class="card">
          <h3 style="font-size:15px;margin-bottom:10px;">Ready to apply?</h3>
          <a routerLink="/job/apply-job" class="btn btn-primary btn-block">Apply now</a>
          <button class="btn btn-secondary btn-block" style="margin-top:8px;" (click)="saveJobToProfile()"
            [disabled]="isjobSaved">

            {{ isjobSaved ? 'Saved' : 'Save' }}

          </button>
          <hr style="border:none;border-top:1px solid var(--line);margin:18px 0;">
          <h3 style="font-size:14px;margin-bottom:6px;">About {{job.companyName}}</h3>
          <p class="muted" style="font-size:13px;">{{job.location}}, IN · {{job.companyName}}</p>
        </div>
      </div>

    </main>
  </div>
</div>
